head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > minlength]<br/>SearchBox 컴포넌트의 최소 입력 문자 길이를 설정합니다.",
    "validation" : [
        "한 문자의 길이를 1 로 계산(다국어 포함)하여 입력값의 최소 길이를 숫자로 설정합니다.",
        "값을 설정하지 않으면 '-1' 로 적용되어 최소 길이 입력을 제한하지 않습니다.",
        "validate() 메소드 실행 시 입력값이 없으면 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "validate() 메소드 실행 시 입력값의 길이가 설정값보다 작으면 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "시스템 기본 메시지는 '최소 n 자리 이상 입력해야 합니다.' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
        "한글 다국어 문자도 한 글자당 길이 1 로 계산되어 minlength 유효성 체크가 적용되어야 합니다.",
        "영문 문자도 한 글자당 길이 1 로 계산되어 minlength 유효성 체크가 적용되어야 합니다.",
        "dataType=number 일때 숫자도 한 글자당 길이 1 로 계산되어 minlength 유효성 체크가 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}

// target1 : minlength=10, 입력값="가나다라마바사"(한글7자) → 7 < 10 → 실패 메시지 출력
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("가나다라마바사");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.check_validate(target1);
}

// target2 : minlength 미설정 → -1 적용, 입력값="가나다라마바사" → 메시지 미출력 (PASS)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("가나다라마바사");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.check_validate(target2);
}

// target3 : minlength=10, 입력값="" (빈 값) → 입력값이 없는 경우도 실패 처리
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("");
};

scwin.btn_validate3_onclick = function (e) {
    scwin.check_validate(target3);
}

// target4 : minlength 미설정(-1), 입력값="" (빈 값) → 최소 입력 제한 없음 → PASS
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("");
};

scwin.btn_validate4_onclick = function (e) {
    scwin.check_validate(target4);
}

// target5 : minlength=10, invalidMessage 설정, 입력값="가" → invalidMessage 출력
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("가");
};

scwin.btn_validate5_onclick = function (e) {
    scwin.check_validate(target5);
}

// target6 : minlength=10, invalidMessageFunc=scwin.fn_msg, 입력값="가" → invalidMessageFunc 반환값 출력
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("가");
};

scwin.btn_validate6_onclick = function (e) {
    scwin.check_validate(target6);
}

// target7 : minlength=10, displaymessage=false, 입력값="가" → 실패 메시지 미출력 (validate 결과만 FAIL)
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("가");
};

scwin.btn_validate7_onclick = function (e) {
    scwin.check_validate(target7);
}

// target8 : minlength=5, 입력값="가나다라마"(한글5자, 경계 일치) → 5 >= 5 → PASS
scwin.btn_setValue8_onclick = function (e) {
    target8.setValue("가나다라마");
};

scwin.btn_validate8_onclick = function (e) {
    scwin.check_validate(target8);
}

// target9 : minlength=5, 입력값="abc"(영문3자) → 3 < 5 → 실패 메시지 출력
scwin.btn_setValue9_onclick = function (e) {
    target9.setValue("abc");
};

scwin.btn_validate9_onclick = function (e) {
    scwin.check_validate(target9);
}

// target10 : minlength=5, 입력값="abcde"(영문5자, 경계 일치) → 5 >= 5 → PASS
scwin.btn_setValue10_onclick = function (e) {
    target10.setValue("abcde");
};

scwin.btn_validate10_onclick = function (e) {
    scwin.check_validate(target10);
}

// target11 : dataType=number, minlength=5, 입력값=123 (숫자 3자리) → 3 < 5 → 실패 메시지 출력
scwin.btn_setValue11_onclick = function (e) {
    target11.setValue(123);
};

scwin.btn_validate11_onclick = function (e) {
    scwin.check_validate(target11);
}

// target12 : dataType=number, minlength=5, 입력값=12345 (숫자 5자리, 경계 일치) → 5 >= 5 → PASS
scwin.btn_setValue12_onclick = function (e) {
    target12.setValue(12345);
};

scwin.btn_validate12_onclick = function (e) {
    scwin.check_validate(target12);
}



scwin.fn_msg = function() {
    return "최소 10 자리 이상 입력 (invalidMessageFunc).";
}
